export const meta = {
  name: 'datum-tdd',
  description: 'Orchestrate datum Act phase TDD lanes — reads tasks.json, enforces RED→GREEN→REFACTOR per task with dependency graph',
  phases: [
    { title: 'Bootstrap', detail: 'Read task graph, verify ratchet baseline' },
    { title: 'RED', detail: 'Write failing tests for all tasks in parallel units' },
    { title: 'Verify RED', detail: 'Confirm each test actually fails before GREEN' },
    { title: 'GREEN', detail: 'Implement fixes, serial within deps, parallel across units' },
    { title: 'REFACTOR', detail: 'Clean up, commit, verify ratchet floor maintained' },
  ],
}

// ── Config ────────────────────────────────────────────────────────────────────
// args shape: { repo: string, tasks_json: string, ratchet_floor: number }
const REPO = (args && args.repo) || '/Volumes/Extra/repos/gitrdunhq/the-record-suite'
const TASKS_JSON = (args && args.tasks_json) || (REPO + '/tasks.json')
const RATCHET_FLOOR = (args && args.ratchet_floor) || 816

// ── Phase 0: Bootstrap ────────────────────────────────────────────────────────
phase('Bootstrap')

const bootstrap = await agent(
  'Read ' + TASKS_JSON + ' and return its full contents as a JSON object. Also run: swift test --package-path ' + REPO + ' 2>&1 | tail -3 to get the current test baseline. Return JSON: { tasks: [...], units: {...}, baseline_tests: number, baseline_suites: number }',
  {
    label: 'bootstrap',
    phase: 'Bootstrap',
    schema: {
      type: 'object',
      properties: {
        tasks: { type: 'array' },
        units: { type: 'object' },
        baseline_tests: { type: 'number' },
        baseline_suites: { type: 'number' },
      },
      required: ['tasks', 'units'],
    },
  }
)

const ratchet = Math.max(RATCHET_FLOOR, bootstrap.baseline_tests || 0)
log('Baseline: ' + ratchet + ' tests. Building dependency graph.')

// ── Helpers ───────────────────────────────────────────────────────────────────
function tasksForUnit(unitId) {
  return bootstrap.tasks.filter(function(t) { return t.unit === unitId })
}

function unitIds() {
  return Object.keys(bootstrap.units)
}

function depsFor(unitId) {
  return (bootstrap.units[unitId] && bootstrap.units[unitId].depends_on) || []
}

function parallelUnits() {
  return unitIds().filter(function(id) { return depsFor(id).length === 0 })
}

function serialChain() {
  // Return units that have deps, sorted by dependency order
  var chain = []
  var remaining = unitIds().filter(function(id) { return depsFor(id).length > 0 })
  var resolved = new Set(parallelUnits())
  var maxIterations = 20
  while (remaining.length > 0 && maxIterations-- > 0) {
    var next = remaining.filter(function(id) {
      return depsFor(id).every(function(d) { return resolved.has(d) })
    })
    next.forEach(function(id) { chain.push(id); resolved.add(id); })
    remaining = remaining.filter(function(id) { return !resolved.has(id) })
  }
  return chain
}

function taskBrief(task) {
  return [
    'Task ID: ' + task.id,
    'Title: ' + task.title,
    'Files to touch: ' + (task.files || []).join(', '),
    'Acceptance criteria: ' + (task.acceptance_criteria || []).join('; '),
    'Red note: ' + (task.red_note || 'Write a test that fails because the bug is present'),
    'Properties to prove: ' + (task.properties || []).join(', '),
    'Repo: ' + REPO,
    'Ratchet floor: ' + ratchet + ' tests — never go below',
    'Branch: ' + ((args && args.branch) || 'datum/epic-30-audit-remediation'),
  ].join('\n')
}

// ── Phase 1: RED — all units in parallel ─────────────────────────────────────
phase('RED')
log('Writing failing tests for ' + bootstrap.tasks.length + ' tasks across ' + unitIds().length + ' units')

// All RED agents run in parallel regardless of unit deps —
// tests don't affect each other at write time.
const redResults = await parallel(bootstrap.tasks.map(function(task) {
  return function() {
    return agent(
      'You are a RED-stage TDD agent. Your ONLY job: write a FAILING test. Do NOT implement any production code.\n\n' +
      taskBrief(task) + '\n\n' +
      'CONSTRAINTS:\n' +
      '- Write the test file only (test files are in Tests/ directories)\n' +
      '- You may ONLY write to test files — never touch source files in task.files yet\n' +
      '- The test MUST FAIL because the bug/missing feature is still present\n' +
      '- Use the existing test framework (check an existing test file in the same Tests/ dir for imports)\n' +
      '- After writing, run: swift test --package-path ' + REPO + ' --filter ' + task.id + ' 2>&1 | tail -10\n' +
      '- If tests PASS, the test is wrong — rewrite until it FAILS for the right reason\n' +
      '- Return JSON: { task_id, test_file, test_name, failure_reason, confirmed_red: boolean }',
      {
        label: 'red:' + task.id,
        phase: 'RED',
        schema: {
          type: 'object',
          properties: {
            task_id: { type: 'string' },
            test_file: { type: 'string' },
            test_name: { type: 'string' },
            failure_reason: { type: 'string' },
            confirmed_red: { type: 'boolean' },
          },
          required: ['task_id', 'confirmed_red'],
        },
      }
    )
  }
}))

const confirmedRed = redResults.filter(Boolean).filter(function(r) { return r.confirmed_red })
const failedRed = redResults.filter(Boolean).filter(function(r) { return !r.confirmed_red })
log('RED: ' + confirmedRed.length + '/' + bootstrap.tasks.length + ' confirmed failing. ' + failedRed.length + ' need attention.')

if (failedRed.length > 0) {
  log('WARNING: These tasks have tests that pass or errored in RED stage: ' + failedRed.map(function(r) { return r.task_id }).join(', '))
}

// ── Phase 2: GREEN — respects dependency order ────────────────────────────────
phase('GREEN')

// Run parallel units concurrently, then serial chain sequentially
const pUnits = parallelUnits()
const sChain = serialChain()

log('Parallel units: ' + pUnits.join(', '))
log('Serial chain: ' + sChain.join(', '))

async function runUnitGreen(unitId) {
  var tasks = tasksForUnit(unitId)
  var results = []
  // Tasks within a unit run sequentially (they may share files)
  for (var i = 0; i < tasks.length; i++) {
    var task = tasks[i]
    var redResult = confirmedRed.find(function(r) { return r.task_id === task.id })
    var result = await agent(
      'You are a GREEN-stage TDD agent. Make the failing test pass with minimal production code.\n\n' +
      taskBrief(task) + '\n\n' +
      'Test signal from RED stage:\n' +
      (redResult ? 'Test: ' + redResult.test_name + '\nFailed because: ' + redResult.failure_reason : 'No RED signal — proceed carefully') + '\n\n' +
      'CONSTRAINTS:\n' +
      '- Write ONLY to these source files: ' + (task.files || []).join(', ') + '\n' +
      '- Do NOT edit test files\n' +
      '- Minimal implementation — only what makes the test pass\n' +
      '- After implementing, run: swift test --package-path ' + REPO + ' 2>&1 | tail -5\n' +
      '- Must show ' + ratchet + '+ tests, 0 failures\n' +
      '- Then commit: git add <files> && git commit -m "<fix message closing the finding>"\n' +
      '- Return JSON: { task_id, files_changed, tests_after, committed: boolean, commit_sha }',
      {
        label: 'green:' + task.id,
        phase: 'GREEN',
        schema: {
          type: 'object',
          properties: {
            task_id: { type: 'string' },
            files_changed: { type: 'array', items: { type: 'string' } },
            tests_after: { type: 'number' },
            committed: { type: 'boolean' },
            commit_sha: { type: 'string' },
          },
          required: ['task_id', 'committed'],
        },
      }
    )
    results.push(result)
  }
  return results
}

// Fan out parallel units, then await serial chain sequentially
const parallelResults = await parallel(pUnits.map(function(uid) {
  return function() { return runUnitGreen(uid) }
}))

var serialResults = []
for (var s = 0; s < sChain.length; s++) {
  var sResults = await runUnitGreen(sChain[s])
  serialResults = serialResults.concat(sResults)
}

var allGreen = parallelResults.flat().concat(serialResults).filter(Boolean)
var committed = allGreen.filter(function(r) { return r.committed })
log('GREEN: ' + committed.length + '/' + bootstrap.tasks.length + ' tasks committed.')

// ── Phase 3: REFACTOR — final validation ──────────────────────────────────────
phase('REFACTOR')

const finalCheck = await agent(
  'Run the full test suite and validate the ratchet floor:\n' +
  'swift test --package-path ' + REPO + ' 2>&1 | tail -10\n\n' +
  'Also run swiftlint if available: swiftlint lint --quiet 2>&1 | head -20\n\n' +
  'Ratchet floor: ' + ratchet + ' tests minimum.\n\n' +
  'Return JSON: { tests: number, suites: number, failures: number, ratchet_ok: boolean, lint_violations: number, summary: string }',
  {
    label: 'final-check',
    phase: 'REFACTOR',
    schema: {
      type: 'object',
      properties: {
        tests: { type: 'number' },
        suites: { type: 'number' },
        failures: { type: 'number' },
        ratchet_ok: { type: 'boolean' },
        lint_violations: { type: 'number' },
        summary: { type: 'string' },
      },
      required: ['tests', 'failures', 'ratchet_ok'],
    },
  }
)

return {
  ratchet_floor: ratchet,
  tasks_total: bootstrap.tasks.length,
  red_confirmed: confirmedRed.length,
  red_failed: failedRed.length,
  green_committed: committed.length,
  final_tests: finalCheck.tests,
  final_failures: finalCheck.failures,
  ratchet_ok: finalCheck.ratchet_ok,
  summary: finalCheck.summary,
}

